import re

def improve(g):
 p=g['pages']
 def gallery():
  return '''<div class="examplecards" id="examples"><article class="examplecard"><a class="examplecover" href="/demos/olive-earth/" aria-label="Open the Indian homeware shop demo"><div class="projectvisual olivevisual"><div class="mininav">OLIVE & EARTH <span>Shop / Materials / About</span></div><div class="olivethumb"><div><small>FOR EVERYDAY INDIAN HOMES</small><h3>A little warmth.<br>For every corner.</h3><span>Browse homeware ↗</span></div><div class="vesselart" role="img" aria-label="Clay vase and serving bowl concept illustration"><i class="vase"></i><i class="bowl"></i></div></div><div class="visualfoot">Clay vase &nbsp; Cotton throw &nbsp; Serving bowl</div></div><span class="coverlabel">Try the shop →</span></a><div class="examplebody"><span class="eyebrow">01 / INDIAN HOMEWARE SHOP DEMO</span><h3>Olive & Earth</h3><p>A simple shop for home and dining objects. Browse categories, check materials, and try adding items to a demo bag.</p><ul><li>Category filters and product information</li><li>Add, remove, and change quantities</li></ul><div class="exampleactions"><a class="btn" href="/demos/olive-earth/">Try shop demo ↗</a><a class="textlink" href="/work/olive-earth/">How it was designed ↗</a></div></div></article><article class="examplecard"><a class="examplecover" href="/demos/form-space/" aria-label="Open the Indian architecture studio demo"><div class="projectvisual archvisual"><div class="mininav">FORM / SPACE <span>Homes / Approach / Enquire</span></div><img src="/assets/courtyard.svg" alt="Original illustration of a courtyard home with shaded spaces" loading="lazy"><div class="archtitle"><h3>Homes with room<br>for everyday life.</h3><small>AANGAN HOUSE / CONCEPT</small></div></div><span class="coverlabel">Explore the studio →</span></a><div class="examplebody"><span class="eyebrow">02 / INDIAN ARCHITECTURE STUDIO DEMO</span><h3>Form / Space</h3><p>A studio website for home and renovation enquiries. Explore a courtyard home and verandah retreat, then try a project brief.</p><ul><li>Project stories and a clear studio approach</li><li>A short, labelled consultation form</li></ul><div class="exampleactions"><a class="btn" href="/demos/form-space/">Try studio demo ↗</a><a class="textlink" href="/work/form-space/">How it was designed ↗</a></div></div></article></div>'''
 for route,(title,body) in list(p.items()):
  body=re.sub(r'<div class="projects">.*?</a></div>',gallery(),body,flags=re.S)
  body=body.replace('See the kind of website<br>we could create.','Two example websites.<br>Try them for yourself.').replace('These two fictional example websites show my design and development approach. They are demonstrations, not client projects.','Explore a homeware shop and an architecture studio designed with Indian visitors in mind. These are fictional demos, not client projects.').replace('Explore the website examples ↗','See both examples ↗')
  body=body.replace('Original ideas, developed<br>into digital experiences.','Example websites<br>you can actually try.').replace('These independent concepts demonstrate my approach to design and website structure. Explore the brief, decisions, and implementation. These are demonstrations, not commissioned projects.','Try an Indian homeware shop or architecture studio. Open a working demo, or read the decisions behind its design. Both are fictional examples, not commissioned projects.')
  body=body.replace('basket','bag').replace('Clay vessel','Clay vase').replace('Linen','Cotton').replace('linen','cotton').replace('Courtyard House','Aangan House').replace('Hillside Pavilion','Verandah Retreat')
  if route=='/work/olive-earth/':body=body.replace('category filtering, expandable product details, material stories, and a page-local basket','category filtering, expandable product details, material stories, and a page-local bag with quantity controls')
  if route=='/':body=body.replace('href="/work/">See example websites','href="#examples">See example websites')
  p[route]=(title,body)
